'use strict';
// Subscribers & plans: netops' own RADIUS (replacing ISPman). Who may log in, at what speed and until when.
const radiusView={tab:'subscribers',q:'',filter:'all',data:null,request:0};
const ksh=n=>'KSh '+Number(n||0).toLocaleString();
const durationText=p=>p.durationValue+' '+(p.durationValue===1?p.durationUnit.replace(/s$/,''):p.durationUnit);
const expiryText=s=>s.expiresAt==null?'No expiry':stamp(s.expiresAt);
const stateBadge=s=>`<span class="status ${s.state==='active'?'online':s.state==='expired'?'warning':'offline'}">${s.state==='active'?'Active':s.state==='expired'?'Expired':'Suspended'}</span>`;
const bytesShort=n=>{const u=['B','KB','MB','GB','TB'];let i=0;n=Number(n)||0;while(n>=1024&&i<u.length-1){n/=1024;i++;}return (n>=10||i===0?Math.round(n):n.toFixed(1))+' '+u[i];};
function radiusForm(title,description,fields,submitLabel,onSubmit){
 $('#editor-title').textContent=title;$('#editor-description').textContent=description;$('#editor-fields').innerHTML=fields;$('#editor-error').textContent='';$('#editor-form [type=submit]').textContent=submitLabel;
 $('#editor-form').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=$('[type=submit]',form);button.disabled=true;try{await onSubmit(Object.fromEntries(new FormData(form)));$('#editor').close();await loadRadius();}catch(error){$('#editor-error').textContent=error.message;}finally{button.disabled=false;}};
 $('#editor').showModal();
}
const radiusField=(label,input)=>`<label>${label}${input}</label>`;
const radiusOptions=(values,current)=>values.map(([v,l])=>`<option value="${h(v)}" ${String(current)===String(v)?'selected':''}>${h(l)}</option>`).join('');
function planEditor(id){const p=radiusView.data.plans.find(x=>x.id===id)||{service:'pppoe',durationValue:30,durationUnit:'days',devices:1,active:true};
 radiusForm(id?'Edit plan':'New plan','Speed, price and how long one payment lasts. Changes apply at each customer\'s next login.',
  radiusField('Plan name',`<input name="name" required maxlength="120" value="${h(p.name||'')}" placeholder="Home 10 Mbps">`)+
  `<div class="form-grid">${radiusField('For',`<select name="service">${radiusOptions([['pppoe','PPPoE'],['hotspot','Hotspot'],['both','PPPoE and Hotspot']],p.service)}</select>`)+radiusField('Price (KSh)',`<input name="price" type="number" min="0" step="1" required value="${h(p.price??'')}">`)+
  radiusField('Download (Mbps)',`<input name="downloadMbps" type="number" min="0.064" step="0.001" required value="${h(p.downloadMbps??'')}">`)+radiusField('Upload (Mbps)',`<input name="uploadMbps" type="number" min="0.064" step="0.001" required value="${h(p.uploadMbps??'')}">`)+
  radiusField('Lasts',`<input name="durationValue" type="number" min="1" max="1000" required value="${h(p.durationValue)}">`)+radiusField('Unit',`<select name="durationUnit">${radiusOptions([['hours','Hours'],['days','Days'],['weeks','Weeks'],['months','Months (30 days)']],p.durationUnit)}</select>`)+
  radiusField('Devices at once (hotspot)',`<input name="devices" type="number" min="1" max="50" value="${h(p.devices)}">`)}</div>`+
  radiusField('Description (optional)',`<input name="description" maxlength="500" value="${h(p.description||'')}">`),
  id?'Save plan':'Create plan',input=>api(id?'radius/plans/'+id:'radius/plans',id?'PATCH':'POST',input));}
function subscriberEditor(id){const d=radiusView.data,s=d.subscribers.find(x=>x.id===id)||{service:'pppoe',status:'active'};
 if(!d.plans.length){toast('Create a plan first');radiusView.tab='plans';paintRadius();return;}
 const expiry=s.expiresAt?new Date(s.expiresAt-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16):'';
 radiusForm(id?'Edit subscriber':'New subscriber',id?'Leave the password empty to keep the current one.':'Leave the password empty to generate one. Without an expiry date the customer starts expired; use Renew once they pay.',
  `<div class="form-grid">${radiusField('Customer name',`<input name="name" required maxlength="120" value="${h(s.name||'')}">`)+radiusField('Phone',`<input name="phone" maxlength="30" value="${h(s.phone||'')}" placeholder="07…">`)+
  radiusField('Username',`<input name="username" required maxlength="64" pattern="[A-Za-z0-9._-]{2,64}" value="${h(s.username||'')}" autocomplete="off">`)+radiusField(id?'New password (optional)':'Password (optional)',`<input name="password" maxlength="64" autocomplete="new-password">`)+
  radiusField('Connection',`<select name="service">${radiusOptions([['pppoe','PPPoE'],['hotspot','Hotspot']],s.service)}</select>`)+radiusField('Plan',`<select name="planId" required>${radiusOptions(d.plans.map(p=>[p.id,p.name+' · '+ksh(p.price)]),s.planId)}</select>`)+
  radiusField('Expires',`<input name="expiresAt" type="datetime-local" value="${expiry}">`)+radiusField('Status',`<select name="status">${radiusOptions([['active','Active'],['suspended','Suspended']],s.status)}</select>`)+
  radiusField('Static IP (optional)',`<input name="staticIp" maxlength="45" value="${h(s.staticIp||'')}" placeholder="10.40.0.50">`)+radiusField('Email (optional)',`<input name="email" type="email" maxlength="120" value="${h(s.email||'')}">`)}</div>`+
  radiusField('Address / notes (optional)',`<input name="notes" maxlength="1000" value="${h(s.notes||'')}">`),
  id?'Save subscriber':'Create subscriber',async input=>{input.expiresAt=input.expiresAt?new Date(input.expiresAt).getTime():'';const saved=await api(id?'radius/subscribers/'+id:'radius/subscribers',id?'PATCH':'POST',input);if(saved.password)setTimeout(()=>showDetails('Login details — '+saved.name,`<p>Give these to the customer. The password is shown once here; admins can reveal it later.</p><dl class="radius-credentials"><dt>Username</dt><dd><code>${h(saved.username)}</code></dd><dt>Password</dt><dd><code>${h(saved.password)}</code></dd></dl><p class="muted">While testing alongside ISPman, the customer logs in as <code>${h(saved.username)}@${h(radiusView.data.settings.realm)}</code>.</p>`),50);});}
async function renewSubscriber(id){const s=radiusView.data.subscribers.find(x=>x.id===id),p=radiusView.data.plans.find(x=>x.id===s?.planId);if(!s||!p)return;
 radiusForm('Renew '+s.name,`Adds ${durationText(p)} per period from ${s.state==='active'&&s.expiresAt?'the current expiry':'now'}. Record the payment under Billing records.`,radiusField('Periods',`<input name="periods" type="number" min="1" max="24" value="1">`)+`<p class="muted">Plan: ${h(p.name)} · ${ksh(p.price)} per period</p>`,'Renew',input=>api('radius/subscribers/'+id+'/renew','POST',{periods:Number(input.periods)}));}
async function revealPassword(id){try{const r=await api('radius/subscribers/'+id+'/password');showDetails('Password',`<p><code>${h(r.password||'—')}</code></p>`);}catch(error){toast(error.message);}}
async function removeRecord(kind,id,label){if(!confirm('Delete '+label+'? This cannot be undone.'))return;try{await api('radius/'+kind+'/'+id,'DELETE');await loadRadius();}catch(error){toast(error.message);}}
function paintRadius(){const d=radiusView.data;if(!d)return;
 $('#radius-metrics').innerHTML=[['Subscribers',d.counts.subscribers,'In the netops RADIUS'],['Active',d.counts.active,'Paid up and allowed online'],['Online now',d.counts.online,'Sessions reported by the routers'],['Expiring in 3 days',d.counts.expiringSoon,'Remind these customers'],['Expired',d.counts.expired,'PPPoE is restricted, hotspot rejected']].map(([t,v,p])=>`<div class="card metric-card"><div><div class="metric-title">${t}</div><div class="metric-value">${Number(v).toLocaleString()}</div><p>${p}</p></div></div>`).join('');
 const q=radiusView.q.toLowerCase(),match=(...v)=>!q||v.join(' ').toLowerCase().includes(q);
 const subs=d.subscribers.filter(s=>(radiusView.filter==='all'||s.state===radiusView.filter||(radiusView.filter==='online'&&s.online))&&match(s.name,s.username,s.phone,s.planName,s.lastMac,s.staticIp));
 $('#radius-subscribers').innerHTML=table(['CUSTOMER','USERNAME','PLAN','STATUS','EXPIRES','LAST SEEN','ACTIONS'],subs,s=>`<tr><td><strong>${h(s.name)}</strong><small>${h([s.phone,s.service==='hotspot'?'Hotspot':'PPPoE'].filter(Boolean).join(' · '))}</small></td><td><code>${h(s.username)}</code>${s.online?'<small class="radius-online">● online</small>':''}</td><td>${h(s.planName)}</td><td>${stateBadge(s)}</td><td>${h(expiryText(s))}</td><td>${s.lastSeen?h(stamp(s.lastSeen)):'<span class="muted">Never</span>'}<small>${h(s.lastMac||'')}</small></td><td class="radius-actions"><button class="button secondary" data-renew="${s.id}">Renew</button><button class="button ghost" data-edit-sub="${s.id}">Edit</button><button class="button ghost" data-pass="${s.id}">Password</button><button class="button ghost" data-del-sub="${s.id}">Delete</button></td></tr>`,d.subscribers.length?'No subscribers match.':'No subscribers yet. Add your first, or import them from ISPman later.');
 $('#radius-plans').innerHTML=table(['PLAN','FOR','SPEED (DOWN / UP)','PRICE','LASTS','DEVICES','SUBSCRIBERS','ACTIONS'],d.plans,p=>`<tr><td><strong>${h(p.name)}</strong><small>${h(p.description||'')}</small></td><td>${{pppoe:'PPPoE',hotspot:'Hotspot',both:'Both'}[p.service]}</td><td>${p.downloadMbps} / ${p.uploadMbps} Mbps</td><td>${ksh(p.price)}</td><td>${h(durationText(p))}</td><td>${p.devices}</td><td>${d.subscribers.filter(s=>s.planId===p.id).length}</td><td class="radius-actions"><button class="button ghost" data-edit-plan="${p.id}">Edit</button><button class="button ghost" data-del-plan="${p.id}">Delete</button></td></tr>`,'No plans yet. Create the packages you sell (e.g. Home 10 Mbps, 30 days, KSh 2,500).');
 $('#radius-sessions').innerHTML=table(['SUBSCRIBER','TYPE','IP / MAC','ROUTER','STARTED','DOWNLOADED','UPLOADED'],d.sessions,s=>`<tr><td><strong>${h(s.username)}</strong></td><td>${s.service==='pppoe'?'PPPoE':'Hotspot'}</td><td>${h(s.ip||'—')}<small>${h(s.mac||'')}</small></td><td>${h(s.nas)}</td><td>${h(stamp(s.startedAt))}</td><td>${bytesShort(s.downloadBytes)}</td><td>${bytesShort(s.uploadBytes)}</td></tr>`,'Nobody is online through the netops RADIUS yet.');
 $('#radius-log').innerHTML=table(['TIME','LOGIN','TYPE','RESULT','REASON','ROUTER / MAC'],d.log,l=>`<tr><td>${h(stamp(l.time))}</td><td><code>${h(l.username)}</code></td><td>${l.service==='pppoe'?'PPPoE':'Hotspot'}</td><td><span class="status ${l.result==='accept'?'online':'offline'}">${l.result==='accept'?'Accepted':'Rejected'}</span></td><td>${h(l.reason)}</td><td>${h(l.nas)}<small>${h(l.mac||'')}</small></td></tr>`,'No login attempts yet.');
 for(const el of document.querySelectorAll(".radius-realm"))el.textContent=d.settings.realm;
 for(const b of document.querySelectorAll('[data-radius-tab]'))b.classList.toggle('active',b.dataset.radiusTab===radiusView.tab);
 for(const p of document.querySelectorAll('[data-radius-panel]'))p.hidden=p.dataset.radiusPanel!==radiusView.tab;
 const on=(sel,fn)=>{for(const b of document.querySelectorAll(sel))b.onclick=()=>fn(Object.values(b.dataset)[0]);};
 on('[data-renew]',renewSubscriber);on('[data-edit-sub]',subscriberEditor);on('[data-pass]',revealPassword);on('[data-del-sub]',id=>removeRecord('subscribers',id,'this subscriber'));on('[data-edit-plan]',planEditor);on('[data-del-plan]',id=>removeRecord('plans',id,'this plan'));
}
async function loadRadius(){const request=++radiusView.request;try{const d=await api('radius');if(request!==radiusView.request||state.page!=='radius')return;radiusView.data=d;paintRadius();}catch(error){if(request===radiusView.request)$('#radius-content').innerHTML=notice('Could not load subscribers',h(error.message),true);}}
function renderRadius(){
 $('#main').innerHTML=heading('Subscribers & plans','Netops\' own RADIUS: who may log in, at what speed and until when. It replaces ISPman one router at a time.','<button class="button secondary" id="radius-new-plan">New plan</button><button class="button primary" id="radius-new-sub">New subscriber</button>')+
 `<div id="radius-content"><div id="radius-metrics" class="dashboard-cards sites-cards radius-cards"><div class="card metric-card"><p>Loading…</p></div></div>
 <div class="sites-tabs" role="tablist">${[['subscribers','Subscribers'],['plans','Plans'],['sessions','Online now'],['log','Login log'],['setup','Router setup']].map(([k,l])=>`<button type="button" role="tab" data-radius-tab="${k}">${l}</button>`).join('')}</div>
 <section class="card sites-panel" data-radius-panel="subscribers"><div class="table-toolbar sites-toolbar radius-toolbar"><input type="search" id="radius-query" placeholder="Search name, username, phone, MAC" aria-label="Search subscribers"><select id="radius-filter" aria-label="Status">${radiusOptions([['all','All subscribers'],['active','Active'],['online','Online now'],['expired','Expired'],['suspended','Suspended']],radiusView.filter)}</select></div><div id="radius-subscribers"></div></section>
 <section class="card sites-panel" data-radius-panel="plans" hidden><div id="radius-plans"></div></section>
 <section class="card sites-panel" data-radius-panel="sessions" hidden><div class="card-header"><div><h2>Online now</h2><p>Sessions the routers reported in the last 15 minutes (accounting every 5 minutes).</p></div></div><div id="radius-sessions"></div></section>
 <section class="card sites-panel" data-radius-panel="log" hidden><div class="card-header"><div><h2>Login log</h2><p>Every login attempt and why it was accepted or rejected (latest 500).</p></div></div><div id="radius-log"></div></section>
 <section class="card sites-panel" data-radius-panel="setup" hidden><div class="card-header"><div><h2>Connect a MikroTik</h2><p>Each router reaches this RADIUS through a private WireGuard tunnel to the netops server. Nothing here changes a router by itself.</p></div></div>
 <ol class="radius-steps"><li><strong>Once on the server:</strong> <code>sudo bash deployment/wireguard/setup-server.sh</code>, open UDP 51820 in Azure, set <code>RADIUS_SECRET</code> and <code>NETWORK_RADIUS_TOKEN</code> in <code>.env</code>, then <code>docker compose --profile radius up -d --build</code>.</li><li><strong>Per router:</strong> <code>sudo bash deployment/wireguard/add-router.sh hEX 2</code> prints the commands to paste on that MikroTik.</li><li><strong>Test without affecting customers:</strong> the router sends only logins ending in <code>@<span class="radius-realm"></span></code> to netops; everyone else stays on ISPman. Log in as <code>username@<span class="radius-realm"></span></code> on PPPoE or the hotspot.</li><li><strong>Switch over</strong> one router at a time once tests pass. ISPman stays as the fallback until you remove it.</li></ol></section></div>`;
 $('#radius-new-plan').onclick=()=>planEditor();$('#radius-new-sub').onclick=()=>subscriberEditor();
 for(const b of document.querySelectorAll('[data-radius-tab]'))b.onclick=()=>{radiusView.tab=b.dataset.radiusTab;paintRadius();};
 $('#radius-query').oninput=e=>{radiusView.q=e.target.value;paintRadius();};$('#radius-filter').onchange=e=>{radiusView.filter=e.target.value;paintRadius();};
 loadRadius();
}
setInterval(()=>{if(state.session?.user&&state.page==='radius'&&!document.hidden&&!$('dialog[open]'))loadRadius();},60000);
